@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Count; i++)
        {
            var stepIndex = i;
            var stepName = Steps[i];
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="step-item @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                @if (isCompleted)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@stepName</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(isCurrent ? "step" : null)">
                        <span class="step-number">@(stepIndex + 1)</span>
                        <span class="step-label">@stepName</span>
                    </span>
                }

                @if (stepIndex < Steps.Count - 1)
                {
                    <span class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></span>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-indicator { margin-bottom: 2rem; }
    .step-list {
        display: flex;
        list-style: none;
        padding: 0;
        margin: 0;
        align-items: center;
    }
    .step-item {
        display: flex;
        align-items: center;
        flex: 1;
    }
    .step-item:last-child { flex: 0; }
    .step-button {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 0.25rem;
        background: none;
        border: none;
        cursor: default;
        padding: 0.25rem;
        min-width: 5rem;
        text-align: center;
    }
    .step-item.completed .step-button { cursor: pointer; }
    .step-item.completed .step-button:hover .step-label { text-decoration: underline; }
    .step-number, .step-icon {
        width: 2rem;
        height: 2rem;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        font-size: 0.875rem;
        border: 2px solid #ccc;
        color: #999;
        background: #fff;
    }
    .step-item.current .step-number {
        border-color: #0d6efd;
        color: #fff;
        background: #0d6efd;
    }
    .step-item.completed .step-icon {
        border-color: #198754;
        color: #fff;
        background: #198754;
    }
    .step-label { font-size: 0.75rem; color: #999; white-space: nowrap; }
    .step-item.current .step-label { color: #0d6efd; font-weight: 600; }
    .step-item.completed .step-label { color: #198754; }
    .step-connector {
        flex: 1;
        height: 2px;
        background: #ccc;
        margin: 0 0.5rem;
        margin-bottom: 1rem;
    }
    .step-connector.completed { background: #198754; }
</style>

@code {
    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public List<string> Steps { get; set; } = [];

    [Parameter]
    public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @Index</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-sm btn-outline-danger remove-btn" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Model.Company"
                   @onchange="e => Update(Model with { Company = (string?)e.Value ?? "" })"
                   required />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Model.Title"
                   @onchange="e => Update(Model with { Title = (string?)e.Value ?? "" })"
                   required />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Model.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Model with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
            @if (!IsCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@Model.EndDate?.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Model with { EndDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
            }
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Model.Description"
                  @onchange="e => Update(Model with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</fieldset>

<style>
    .work-entry-form {
        border: 1px solid #dee2e6;
        border-radius: 0.5rem;
        padding: 1rem;
        margin-bottom: 1rem;
        position: relative;
    }
    .work-entry-form legend { font-weight: 600; font-size: 0.95rem; }
    .remove-btn { position: absolute; top: 0.75rem; right: 0.75rem; }
    .form-row { display: flex; gap: 1rem; margin-bottom: 0.75rem; }
    .form-row .form-group { flex: 1; }
    .form-group { margin-bottom: 0.75rem; }
    .form-group label { display: block; font-size: 0.875rem; margin-bottom: 0.25rem; font-weight: 500; }
    .form-group input[type="text"],
    .form-group input[type="date"],
    .form-group textarea {
        width: 100%;
        padding: 0.375rem 0.5rem;
        border: 1px solid #ced4da;
        border-radius: 0.25rem;
        font-size: 0.9rem;
        box-sizing: border-box;
    }
    .checkbox-label {
        display: inline-flex !important;
        align-items: center;
        gap: 0.5rem;
        font-weight: normal !important;
        margin-bottom: 0.5rem;
    }
    .checkbox-label input[type="checkbox"] { width: auto; }
</style>

@code {
    [Parameter, EditorRequired]
    public WorkEntry Model { get; set; } = default!;

    [Parameter]
    public int Index { get; set; } = 1;

    [Parameter]
    public bool ShowRemove { get; set; }

    [Parameter]
    public EventCallback<WorkEntry> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Model.EndDate is null;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Model with { EndDate = null }
            : Model with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }
}

@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<fieldset class="reference-form">
    <legend>Reference @Index</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-sm btn-outline-danger ref-remove-btn" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Model.Name"
                   @onchange="e => Update(Model with { Name = (string?)e.Value ?? "" })" required />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Model.Relationship"
                   @onchange="e => Update(Model with { Relationship = (string?)e.Value ?? "" })" required />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Model.Email"
                   @onchange="e => Update(Model with { Email = (string?)e.Value ?? "" })" required />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Model.Phone"
                   @onchange="e => Update(Model with { Phone = (string?)e.Value ?? "" })" required />
        </div>
    </div>
</fieldset>

<style>
    .reference-form {
        border: 1px solid #dee2e6;
        border-radius: 0.5rem;
        padding: 1rem;
        margin-bottom: 1rem;
        position: relative;
    }
    .reference-form legend { font-weight: 600; font-size: 0.95rem; }
    .ref-remove-btn { position: absolute; top: 0.75rem; right: 0.75rem; }
</style>

@code {
    [Parameter, EditorRequired]
    public Reference Model { get; set; } = default!;

    [Parameter]
    public int Index { get; set; } = 1;

    [Parameter]
    public bool ShowRemove { get; set; }

    [Parameter]
    public EventCallback<Reference> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private void Update(Reference updated) => OnChanged.InvokeAsync(updated);
}

