+@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply
+
+<nav class="step-indicator" aria-label="Application steps">
+    <ol class="step-list">
+        @for (int i = 0; i < Steps.Count; i++)
+        {
+            var stepIndex = i;
+            var stepName = Steps[i];
+            var isCompleted = stepIndex < CurrentStep;
+            var isCurrent = stepIndex == CurrentStep;
+            var isFuture = stepIndex > CurrentStep;
+
+            <li class="step-item @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
+                @if (isCompleted)
+                {
+                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
+                        <span class="step-icon">&#10003;</span>
+                        <span class="step-label">@stepName</span>
+                    </button>
+                }
+                else
+                {
+                    <span class="step-button" aria-current="@(isCurrent ? "step" : null)">
+                        <span class="step-number">@(stepIndex + 1)</span>
+                        <span class="step-label">@stepName</span>
+                    </span>
+                }
+
+                @if (stepIndex < Steps.Count - 1)
+                {
+                    <span class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></span>
+                }
+            </li>
+        }
+    </ol>
+</nav>
+
+<style>
+    .step-indicator { margin-bottom: 2rem; }
+    .step-list {
+        display: flex;
+        list-style: none;
+        padding: 0;
+        margin: 0;
+        align-items: center;
+    }
+    .step-item {
+        display: flex;
+        align-items: center;
+        flex: 1;
+    }
+    .step-item:last-child { flex: 0; }
+    .step-button {
+        display: flex;
+        flex-direction: column;
+        align-items: center;
+        gap: 0.25rem;
+        background: none;
+        border: none;
+        cursor: default;
+        padding: 0.25rem;
+        min-width: 5rem;
+        text-align: center;
+    }
+    .step-item.completed .step-button { cursor: pointer; }
+    .step-item.completed .step-button:hover .step-label { text-decoration: underline; }
+    .step-number, .step-icon {
+        width: 2rem;
+        height: 2rem;
+        border-radius: 50%;
+        display: flex;
+        align-items: center;
+        justify-content: center;
+        font-weight: bold;
+        font-size: 0.875rem;
+        border: 2px solid #ccc;
+        color: #999;
+        background: #fff;
+    }
+    .step-item.current .step-number {
+        border-color: #0d6efd;
+        color: #fff;
+        background: #0d6efd;
+    }
+    .step-item.completed .step-icon {
+        border-color: #198754;
+        color: #fff;
+        background: #198754;
+    }
+    .step-label { font-size: 0.75rem; color: #999; white-space: nowrap; }
+    .step-item.current .step-label { color: #0d6efd; font-weight: 600; }
+    .step-item.completed .step-label { color: #198754; }
+    .step-connector {
+        flex: 1;
+        height: 2px;
+        background: #ccc;
+        margin: 0 0.5rem;
+        margin-bottom: 1rem;
+    }
+    .step-connector.completed { background: #198754; }
+</style>
+
+@code {
+    [Parameter, EditorRequired]
+    public int CurrentStep { get; set; }
+
+    [Parameter, EditorRequired]
+    public List<string> Steps { get; set; } = [];
+
+    [Parameter]
+    public EventCallback<int> OnStepClicked { get; set; }
+}
