@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Model.FullName"
               @onchange="e => UpdateModel(Model with { FullName = (string?)e.Value ?? "" })" required />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Model.Email"
                   @onchange="e => UpdateModel(Model with { Email = (string?)e.Value ?? "" })" required />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Model.Phone"
                   @onchange="e => UpdateModel(Model with { Phone = (string?)e.Value ?? "" })" required />
        </div>
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address"
                  @onchange="e => UpdateModel(Model with { Address = (string?)e.Value ?? "" })"></textarea>
    </div>

    <div class="step-actions">
        <span></span>
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next →")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public PersonalInfo Model { get; set; } = default!;

    [Parameter]
    public EventCallback<PersonalInfo> OnModelChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage { get; set; }
    private bool IsValidating { get; set; }

    private void UpdateModel(PersonalInfo updated) => OnModelChanged.InvokeAsync(updated);

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Model.Email);
            IsValidating = false;

            if (!isValid)
            {
                ErrorMessage = "The email address provided is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Model="@Entries[index]"
                       Index="@(index + 1)"
                       ShowRemove="@(Entries.Count > 1)"
                       OnChanged="entry => UpdateEntry(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-actions">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<WorkEntry> Entries { get; set; } = [];

    [Parameter]
    public EventCallback<List<WorkEntry>> OnEntriesChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage { get; set; }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        var list = new List<WorkEntry>(Entries);
        list[index] = updated;
        OnEntriesChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<WorkEntry>(Entries);
        list.RemoveAt(index);
        OnEntriesChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<WorkEntry>(Entries)
        {
            new("", "", DateTime.Today, null, "")
        };
        OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (Entries.Any(e => string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)))
        {
            ErrorMessage = "Company name and job title are required for each position.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

