                   @onchange="e => UpdateModel(Model with { Phone = (string?)e.Value ?? "" })" required />
        </div>
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address"
                  @onchange="e => UpdateModel(Model with { Address = (string?)e.Value ?? "" })"></textarea>
    </div>

    <div class="step-actions">
        <span></span>
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next →")
        </button>
    </div>
