@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Model="@References[index]"
                       Index="@(index + 1)"
                       ShowRemove="@(References.Count > 1)"
                       OnChanged="r => UpdateReference(index, r)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="step-actions">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Reference> References { get; set; } = [];

    [Parameter]
    public EventCallback<List<Reference>> OnReferencesChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage { get; set; }

    private void UpdateReference(int index, Reference updated)
    {
        var list = new List<Reference>(References);
        list[index] = updated;
        OnReferencesChanged.InvokeAsync(list);
    }

    private void RemoveReference(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnReferencesChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new("", "", "", "")
        };
        OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Count < 2)
        {
            ErrorMessage = "Please provide at least 2 references.";
            return;
        }

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) ||
                                string.IsNullOrWhiteSpace(r.Relationship) ||
                                string.IsNullOrWhiteSpace(r.Email) ||
                                string.IsNullOrWhiteSpace(r.Phone)))
        {
            ErrorMessage = "All fields are required for each reference.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

