@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="@MaxLength" value="@CoverLetter"
                  @oninput="HandleInput"></textarea>
        <div class="char-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

<style>
    .char-count {
        text-align: right;
        font-size: 0.8rem;
        color: #6c757d;
        margin-top: 0.25rem;
    }
    .char-count.over-limit { color: #dc3545; font-weight: 600; }
</style>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired]
    public string CoverLetter { get; set; } = "";

    [Parameter]
    public EventCallback<string> OnCoverLetterChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage { get; set; }

    private void HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? "";
        if (value.Length > MaxLength)
            value = value[..MaxLength];
        OnCoverLetterChanged.InvokeAsync(value);
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

