toolArgs.file_text:
@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h3>Application Submitted!</h3>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@ApplicationId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <h3>Review & Submit</h3>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <div class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") &mdash;
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email &middot; @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
        </section>

        <div class="step-actions">
            <button type="button" class="btn btn-secondary" @onclick="OnBack">← Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

<style>
    .review-section {
        border: 1px solid #dee2e6;
        border-radius: 0.5rem;
        padding: 1rem;
        margin-bottom: 1rem;
    }
    .review-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 0.5rem;
    }
    .review-header h4 { margin: 0; }
    .btn-link {
        background: none;
        border: none;
        color: #0d6efd;
        cursor: pointer;
        font-size: 0.875rem;
        text-decoration: underline;
        padding: 0;
    }
    .btn-link:hover { color: #0a58ca; }
    dl { display: grid; grid-template-columns: 8rem 1fr; gap: 0.25rem 1rem; margin: 0; }
    dt { font-weight: 600; font-size: 0.875rem; color: #6c757d; }
    dd { margin: 0; }
    .review-work-entry { margin-bottom: 0.75rem; }
    .review-dates { font-size: 0.85rem; color: #6c757d; }
    .review-description { font-size: 0.9rem; margin: 0.25rem 0 0; }
    .review-reference { margin-bottom: 0.5rem; }
    .review-cover-letter { white-space: pre-wrap; }
    .confirmation { text-align: center; padding: 2rem; }
    .confirmation-icon {
        width: 4rem;
        height: 4rem;
        border-radius: 50%;
        background: #198754;
        color: #fff;
        font-size: 2rem;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        margin-bottom: 1rem;
    }
    .application-id {
        font-size: 1.5rem;
        font-weight: 700;
        color: #0d6efd;
        margin: 1rem 0;
    }
</style>

@code {
    [Parameter, EditorRequired]
    public PersonalInfo Personal { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<WorkEntry> WorkEntries { get; set; } = [];

    [Parameter, EditorRequired]
    public List<Reference> References { get; set; } = [];

    [Parameter, EditorRequired]
    public string CoverLetter { get; set; } = "";

    [Parameter]
    public EventCallback<int> OnEditStep { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    [Parameter]
    public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }
    private string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        ErrorMessage = null;
        IsSubmitting = true;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

