@page "/apply"
@namespace sv_93200b036aa24b7298cf6130047a1f71.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_93200b036aa24b7298cf6130047a1f71.Models
@using sv_93200b036aa24b7298cf6130047a1f71.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep"
                   Steps="@_stepNames"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@_personalInfo"
                              OnModelChanged="p => _personalInfo = p"
                              OnNext="() => GoToStep(1)"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;

        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnEntriesChanged="e => _workEntries = e"
                             OnNext="() => GoToStep(2)"
                             OnBack="() => GoToStep(0)" />
            break;

        case 2:
            <ReferencesStep References="@_references"
                            OnReferencesChanged="r => _references = r"
                            OnNext="() => GoToStep(3)"
                            OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnCoverLetterChanged="c => _coverLetter = c"
                             OnNext="() => GoToStep(4)"
                             OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <ReviewStep Personal="@_personalInfo"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="() => GoToStep(3)"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

<style>
    .apply-page {
        max-width: 48rem;
        margin: 0 auto;
        padding: 2rem 1rem;
    }
    .apply-page h2 { margin-bottom: 1.5rem; }
    .step-content { margin-top: 1rem; }
    .step-actions {
        display: flex;
        justify-content: space-between;
        margin-top: 1.5rem;
        padding-top: 1rem;
        border-top: 1px solid #dee2e6;
    }
    .btn {
        padding: 0.5rem 1.25rem;
        border: 1px solid transparent;
        border-radius: 0.375rem;
        font-size: 0.9rem;
        cursor: pointer;
    }
    .btn-primary { background: #0d6efd; color: #fff; border-color: #0d6efd; }
    .btn-primary:hover { background: #0b5ed7; }
    .btn-primary:disabled { background: #6c9dfc; cursor: not-allowed; }
    .btn-secondary { background: #6c757d; color: #fff; border-color: #6c757d; }
    .btn-secondary:hover { background: #5c636a; }
    .btn-success { background: #198754; color: #fff; border-color: #198754; }
    .btn-success:hover { background: #157347; }
    .btn-success:disabled { background: #6bba8f; cursor: not-allowed; }
    .btn-lg { padding: 0.75rem 2rem; font-size: 1rem; }
    .btn-outline-secondary {
        background: #fff;
        color: #6c757d;
        border: 1px solid #6c757d;
    }
    .btn-outline-secondary:hover { background: #6c757d; color: #fff; }
    .btn-outline-danger {
        background: #fff;
        color: #dc3545;
        border: 1px solid #dc3545;
        font-size: 0.8rem;
        padding: 0.2rem 0.5rem;
    }
    .btn-outline-danger:hover { background: #dc3545; color: #fff; }
    .btn-sm { padding: 0.2rem 0.5rem; font-size: 0.8rem; }
    .alert {
        padding: 0.75rem 1rem;
        border-radius: 0.375rem;
        margin-bottom: 1rem;
    }
    .alert-danger { background: #f8d7da; color: #842029; border: 1px solid #f5c2c7; }
</style>

@code {
    private readonly List<string> _stepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private int _currentStep;
    private PersonalInfo _personalInfo = new("", "", "", "");
    private List<WorkEntry> _workEntries = [new("", "", DateTime.Today, null, "")];
    private List<Reference> _references = [new("", "", "", ""), new("", "", "", "")];
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            _personalInfo,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

